        collectAddrs(tree, as)
        const seen = new Map()
        for (const a of as) seen.set(a.name, a)
        names = [...seen.values()].sort((a, b) => a.col - b.col || a.row - b.row).map((a) => a.name)
      }
    }
    out.push(`${name}:` + names.map((x) => ' ' + x).join(''))
  }
}
